BEGIN;
SET LOCAL lock_timeout='5min';
SET LOCAL statement_timeout='15min';
SELECT pg_advisory_xact_lock(84746004);
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN
 IF to_regclass('public.hsd_service_categories') IS NULL OR to_regclass('public.hsd_technical_plan_versions') IS NULL OR to_regclass('public.hsd_sellable_versions') IS NULL THEN RAISE EXCEPTION 'UMZ1-UMZ3 HomeService baseline missing'; END IF;
 IF to_regclass('public.missions') IS NULL THEN RAISE EXCEPTION 'CARELINK canonical public.missions table missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='missions' AND column_name='id' AND data_type IN('bigint','integer')) THEN RAISE EXCEPTION 'CARELINK missions.id must be bigint/integer'; END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='missions' AND column_name='mission_kind') THEN RAISE EXCEPTION 'CARELINK mission_kind column missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='missions' AND column_name='parent_mission_id') THEN RAISE EXCEPTION 'CARELINK parent_mission_id column missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='missions' AND column_name='mission_group_id') THEN RAISE EXCEPTION 'CARELINK mission_group_id column missing'; END IF;
END $$;
CREATE TABLE IF NOT EXISTS public.hsd_handoff_requests(id uuid primary key default gen_random_uuid(),tenant_id text not null,code text not null,status text not null default 'draft',sellable_id uuid not null references public.hsd_sellables(id) on delete restrict,sellable_version_id uuid not null references public.hsd_sellable_versions(id) on delete restrict,technical_plan_version_id uuid not null references public.hsd_technical_plan_versions(id) on delete restrict,category_version_id uuid references public.hsd_service_versions(id) on delete restrict,universe text not null check(universe in('b2c','b2b')),customer_ref text not null default '',beneficiary_refs text[] not null default '{}',customer_snapshot jsonb not null default '{}',beneficiary_snapshot jsonb not null default '[]',operational_contacts jsonb not null default '{}',access_instructions jsonb not null default '{}',safety_blockers text[] not null default '{}',mission_count int not null default 0,total_minutes int not null default 0,snapshot_hash text,idempotency_key text not null,blueprint_summary jsonb not null default '{}',preflight_status text not null default 'not_run',last_preflight_run_id uuid,reconciliation_status text not null default 'not_run',carelink_parent_mission_id bigint,last_failure text,approved_by text,approved_at timestamptz,created_by text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,idempotency_key));
ALTER TABLE public.hsd_handoff_requests ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS hsd_handoff_requests_tenant_select ON public.hsd_handoff_requests;
CREATE POLICY hsd_handoff_requests_tenant_select ON public.hsd_handoff_requests FOR SELECT TO authenticated USING (tenant_id=coalesce((nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'tenant_id'),'__no_tenant__'));
GRANT SELECT ON public.hsd_handoff_requests TO authenticated; GRANT ALL ON public.hsd_handoff_requests TO service_role;
CREATE TABLE IF NOT EXISTS public.hsd_handoff_request_dates(id uuid primary key default gen_random_uuid(),tenant_id text not null,handoff_id uuid not null references public.hsd_handoff_requests(id) on delete cascade,service_date date not null,start_time time not null,end_time time not null,duration_minutes int not null check(duration_minutes>0),sequence int not null,daily_objective text not null default '',status text not null default 'confirmed',carelink_mission_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(handoff_id,sequence),unique(handoff_id,service_date,start_time,end_time));
