CREATE OR REPLACE FUNCTION public.hsd_handoff_immutable_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Committed HomeService handoff records are immutable'; END $$;
DO $$ DECLARE x text; BEGIN FOREACH x IN ARRAY ARRAY['hsd_handoff_source_snapshots','hsd_handoff_approval_decisions','hsd_handoff_transmission_records','hsd_handoff_carelink_links','hsd_handoff_mobile_brief_versions','hsd_handoff_amendment_decisions','hsd_handoff_amendment_propagations'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS trg_%I_immutable ON public.%I',x,x); EXECUTE format('CREATE TRIGGER trg_%I_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.hsd_handoff_immutable_guard()',x,x); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.hsd_handoff_request_commit_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IN('committed','committed_with_projection_failure','reconciled') AND (NEW.sellable_version_id,NEW.technical_plan_version_id,NEW.category_version_id,NEW.customer_ref,NEW.beneficiary_refs,NEW.mission_count,NEW.total_minutes,NEW.snapshot_hash,NEW.idempotency_key) IS DISTINCT FROM (OLD.sellable_version_id,OLD.technical_plan_version_id,OLD.category_version_id,OLD.customer_ref,OLD.beneficiary_refs,OLD.mission_count,OLD.total_minutes,OLD.snapshot_hash,OLD.idempotency_key) THEN RAISE EXCEPTION 'Committed handoff source truth is immutable; use an amendment'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_hsd_handoff_request_commit_guard ON public.hsd_handoff_requests;
CREATE TRIGGER trg_hsd_handoff_request_commit_guard BEFORE UPDATE ON public.hsd_handoff_requests FOR EACH ROW EXECUTE FUNCTION public.hsd_handoff_request_commit_guard();

CREATE OR REPLACE VIEW public.hsd_handoff_registry_v AS
SELECT h.*,coalesce((SELECT jsonb_agg(b.beneficiary_ref) FROM public.hsd_handoff_beneficiary_snapshots b WHERE b.handoff_id=h.id),'[]'::jsonb) beneficiary_snapshot_refs,
       (SELECT count(*) FROM public.hsd_handoff_preflight_findings f WHERE f.handoff_id=h.id AND f.status='open' AND f.blocking) open_blocker_count,
       (SELECT count(*) FROM public.hsd_handoff_carelink_links l WHERE l.handoff_id=h.id AND l.target_type='sub_mission') linked_sub_mission_count
FROM public.hsd_handoff_requests h;
CREATE OR REPLACE VIEW public.hsd_handoff_mapping_registry_v AS
SELECT r.id,r.tenant_id,r.domain,r.source_code,r.target_value,r.mapping_state,r.version_number,r.status,r.effective_from,r.effective_to,r.usage_count,r.last_failure,p.code profile_code,p.name_fr profile_name
FROM public.hsd_handoff_mapping_rules r LEFT JOIN public.hsd_handoff_mapping_profiles p ON p.id=r.profile_id;
GRANT SELECT ON public.hsd_handoff_registry_v,public.hsd_handoff_mapping_registry_v TO authenticated,service_role;

CREATE OR REPLACE FUNCTION public.hsd_commit_carelink_handoff_core(p_handoff_id uuid,p_actor_id text,p_correlation_id uuid)
RETURNS TABLE(parent_mission_id bigint,sub_missions jsonb,transmission_id uuid,idempotency_key text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE h public.hsd_handoff_requests%ROWTYPE; pb public.hsd_handoff_parent_blueprints%ROWTYPE; t_id uuid; p_id bigint; s record; s_id bigint; result_subs jsonb:='[]'::jsonb; existing_t public.hsd_handoff_transmissions%ROWTYPE;
BEGIN
 SELECT * INTO h FROM public.hsd_handoff_requests WHERE id=p_handoff_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Handoff not found'; END IF;
 SELECT * INTO existing_t FROM public.hsd_handoff_transmissions WHERE handoff_id=p_handoff_id AND status IN('committed','committed_with_projection_failure','reconciled') ORDER BY created_at DESC LIMIT 1;
 IF FOUND THEN RETURN QUERY SELECT existing_t.parent_mission_id,coalesce((SELECT jsonb_agg(jsonb_build_object('blueprint_id',l.source_blueprint_id,'mission_id',l.carelink_mission_id) ORDER BY l.created_at) FROM public.hsd_handoff_carelink_links l WHERE l.transmission_id=existing_t.id AND l.target_type='sub_mission'),'[]'::jsonb),existing_t.id,h.idempotency_key; RETURN; END IF;
 IF h.status<>'approved' OR h.preflight_status<>'ready' THEN RAISE EXCEPTION 'Approved handoff and READY preflight required'; END IF;
 IF EXISTS(SELECT 1 FROM public.hsd_handoff_preflight_findings f WHERE f.handoff_id=h.id AND f.status='open' AND f.blocking) THEN RAISE EXCEPTION 'Open blocking findings prevent commit'; END IF;
 SELECT * INTO pb FROM public.hsd_handoff_parent_blueprints WHERE handoff_id=h.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Parent blueprint missing'; END IF;
 t_id:=gen_random_uuid();
 INSERT INTO public.hsd_handoff_transmissions(id,tenant_id,handoff_id,status,projection_status,idempotency_key,correlation_id,started_at,committed_by) VALUES(t_id,h.tenant_id,h.id,'committing','pending',h.idempotency_key,p_correlation_id,now(),p_actor_id);
 INSERT INTO public.missions(family_id,caregiver_id,service_type,mission_date,start_time,end_time,status,lifecycle_stage,mission_kind,mission_group_id,recurrence_type,recurrence_rule,recurrence_start_date,recurrence_end_date,dossier_status,dossier_reference,city,zone,notes,urgency,risk_level,internal_procedure_level,service_family,mission_scope,report_status,validation_status,readiness_status)
 VALUES(null,null,coalesce(pb.blueprint->>'serviceType','HomeService'),nullif(pb.blueprint->>'missionDate','')::date,nullif(pb.blueprint->>'startTime','')::time,nullif(pb.blueprint->>'endTime','')::time,'draft','ready_for_assignment','dossier',h.id,'dated_sessions',jsonb_build_object('source','homeservice_design_umz4','handoffId',h.id),nullif(pb.blueprint->>'missionDate','')::date,(SELECT max(service_date) FROM public.hsd_handoff_request_dates WHERE handoff_id=h.id),'active',coalesce(pb.blueprint->>'dossierReference',h.code),pb.blueprint->>'city',null,pb.blueprint->>'notes','standard','normal','homeservice_design_umz4',coalesce(pb.blueprint->>'serviceFamily',pb.blueprint->>'serviceType'),'sellable_handoff','pending','pending','pending') RETURNING id INTO p_id;
 UPDATE public.hsd_handoff_parent_blueprints SET carelink_mission_id=p_id,mapping_status='committed',updated_at=now() WHERE handoff_id=h.id;
 INSERT INTO public.hsd_handoff_carelink_links(tenant_id,handoff_id,transmission_id,source_type,source_blueprint_id,target_type,carelink_mission_id) VALUES(h.tenant_id,h.id,t_id,'parent_blueprint',pb.id,'parent_mission',p_id);
 INSERT INTO public.hsd_handoff_transmission_records(tenant_id,transmission_id,handoff_id,stage,target_table,target_id,source_blueprint_id,status) VALUES(h.tenant_id,t_id,h.id,'core','missions',p_id::text,pb.id,'committed');
 FOR s IN SELECT * FROM public.hsd_handoff_sub_mission_blueprints WHERE handoff_id=h.id ORDER BY sequence LOOP
  INSERT INTO public.missions(family_id,caregiver_id,service_type,mission_date,start_time,end_time,status,lifecycle_stage,mission_kind,parent_mission_id,mission_group_id,occurrence_index,dossier_status,dossier_reference,city,notes,urgency,risk_level,service_family,mission_scope,report_status,validation_status,readiness_status)
  VALUES(null,null,coalesce(pb.blueprint->>'serviceType','HomeService'),s.service_date,s.start_time,s.end_time,'draft','ready_for_assignment','sub_mission',p_id,h.id,s.sequence,'active',coalesce(pb.blueprint->>'dossierReference',h.code)||'*'||s.sequence,coalesce(pb.blueprint->>'city',''),s.daily_objective,'standard','normal',coalesce(pb.blueprint->>'serviceFamily',pb.blueprint->>'serviceType'),'sellable_handoff','pending','pending','pending') RETURNING id INTO s_id;
  UPDATE public.hsd_handoff_sub_mission_blueprints SET carelink_mission_id=s_id,mapping_status='committed',updated_at=now() WHERE id=s.id;
  UPDATE public.hsd_handoff_request_dates SET carelink_mission_id=s_id,status='committed',updated_at=now() WHERE id=s.source_date_id;
  INSERT INTO public.hsd_handoff_carelink_links(tenant_id,handoff_id,transmission_id,source_type,source_blueprint_id,target_type,carelink_mission_id) VALUES(h.tenant_id,h.id,t_id,'sub_mission_blueprint',s.id,'sub_mission',s_id);
  INSERT INTO public.hsd_handoff_transmission_records(tenant_id,transmission_id,handoff_id,stage,target_table,target_id,source_blueprint_id,status) VALUES(h.tenant_id,t_id,h.id,'core','missions',s_id::text,s.id,'committed');
  result_subs:=result_subs||jsonb_build_array(jsonb_build_object('blueprint_id',s.id,'mission_id',s_id));
 END LOOP;
 IF jsonb_array_length(result_subs)<>h.mission_count THEN RAISE EXCEPTION 'Atomic mission count mismatch'; END IF;
 UPDATE public.hsd_handoff_transmissions SET status='committed',parent_mission_id=p_id,sub_mission_count=jsonb_array_length(result_subs),completed_at=now() WHERE id=t_id;
 UPDATE public.hsd_handoff_requests SET status='committed',carelink_parent_mission_id=p_id,updated_at=now() WHERE id=h.id;
 UPDATE public.hsd_handoff_idempotency_keys SET status='completed',result=jsonb_build_object('parentMissionId',p_id,'subMissions',result_subs),completed_at=now() WHERE handoff_id=h.id;
 INSERT INTO public.hsd_handoff_events(tenant_id,handoff_id,event_type,actor_id,correlation_id,payload) VALUES(h.tenant_id,h.id,'homeservice.handoff.committed',p_actor_id,p_correlation_id,jsonb_build_object('parentMissionId',p_id,'subMissions',result_subs));
 RETURN QUERY SELECT p_id,result_subs,t_id,h.idempotency_key;
END $$;
REVOKE ALL ON FUNCTION public.hsd_commit_carelink_handoff_core(uuid,text,uuid) FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.hsd_commit_carelink_handoff_core(uuid,text,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.hsd_reconcile_carelink_handoff(p_handoff_id uuid,p_actor_id text,p_correlation_id uuid)
RETURNS TABLE(status text,critical_count int,warning_count int,summary jsonb)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE h public.hsd_handoff_requests%ROWTYPE; r_id uuid:=gen_random_uuid(); expected_count int; actual_count int; crit int:=0; warn int:=0; v_rows int; result_status text; result_summary jsonb;
BEGIN
 SELECT * INTO h FROM public.hsd_handoff_requests WHERE id=p_handoff_id;
 IF NOT FOUND OR h.carelink_parent_mission_id IS NULL THEN RAISE EXCEPTION 'Committed handoff required'; END IF;
 INSERT INTO public.hsd_handoff_reconciliation_runs(id,tenant_id,handoff_id,status,correlation_id,run_by,started_at) VALUES(r_id,h.tenant_id,h.id,'running',p_correlation_id,p_actor_id,now());
 expected_count:=h.mission_count;
 SELECT count(*) INTO actual_count FROM public.missions WHERE parent_mission_id=h.carelink_parent_mission_id AND mission_kind='sub_mission';
 IF expected_count<>actual_count THEN INSERT INTO public.hsd_handoff_reconciliation_findings(tenant_id,reconciliation_run_id,handoff_id,domain,severity,expected_value,actual_value,detail) VALUES(h.tenant_id,r_id,h.id,'mission_count','critical',to_jsonb(expected_count),to_jsonb(actual_count),'Nombre de sous-missions différent du snapshot.'); crit:=crit+1; END IF;
 INSERT INTO public.hsd_handoff_reconciliation_findings(tenant_id,reconciliation_run_id,handoff_id,domain,severity,expected_value,actual_value,detail)
 SELECT h.tenant_id,r_id,h.id,'mission_dates','critical',to_jsonb(d.service_date),to_jsonb(m.mission_date),'Date CARELINK différente du snapshot.' FROM public.hsd_handoff_request_dates d JOIN public.missions m ON m.id=d.carelink_mission_id WHERE d.handoff_id=h.id AND m.mission_date IS DISTINCT FROM d.service_date;
 GET DIAGNOSTICS v_rows=ROW_COUNT; crit:=crit+v_rows;
 INSERT INTO public.hsd_handoff_reconciliation_findings(tenant_id,reconciliation_run_id,handoff_id,domain,severity,expected_value,actual_value,detail)
 SELECT h.tenant_id,r_id,h.id,'mission_times','critical',jsonb_build_object('start',d.start_time,'end',d.end_time),jsonb_build_object('start',m.start_time,'end',m.end_time),'Fenêtre CARELINK différente du snapshot.' FROM public.hsd_handoff_request_dates d JOIN public.missions m ON m.id=d.carelink_mission_id WHERE d.handoff_id=h.id AND (m.start_time IS DISTINCT FROM d.start_time OR m.end_time IS DISTINCT FROM d.end_time);
 GET DIAGNOSTICS v_rows=ROW_COUNT; crit:=crit+v_rows;
 INSERT INTO public.hsd_handoff_reconciliation_findings(tenant_id,reconciliation_run_id,handoff_id,domain,severity,expected_value,actual_value,detail)
 SELECT h.tenant_id,r_id,h.id,'programme_lines','warning',to_jsonb((SELECT count(*) FROM public.hsd_handoff_programme_blueprints p WHERE p.handoff_id=h.id)),to_jsonb((SELECT count(*) FROM public.mission_program_lines mpl JOIN public.missions sm ON sm.id=mpl.mission_id WHERE sm.parent_mission_id=h.carelink_parent_mission_id)),'Projection programme incomplète.' WHERE (SELECT count(*) FROM public.hsd_handoff_programme_blueprints p WHERE p.handoff_id=h.id)<>(SELECT count(*) FROM public.mission_program_lines mpl JOIN public.missions sm ON sm.id=mpl.mission_id WHERE sm.parent_mission_id=h.carelink_parent_mission_id);
 GET DIAGNOSTICS v_rows=ROW_COUNT; warn:=warn+v_rows;
 result_status:=CASE WHEN crit>0 THEN 'critical' WHEN warn>0 THEN 'warning' ELSE 'reconciled' END;
 result_summary:=jsonb_build_object('expectedMissionCount',expected_count,'actualMissionCount',actual_count,'criticalCount',crit,'warningCount',warn);
 UPDATE public.hsd_handoff_reconciliation_runs SET status=result_status,critical_count=crit,warning_count=warn,summary=result_summary,completed_at=now() WHERE id=r_id;
 UPDATE public.hsd_handoff_requests SET reconciliation_status=result_status,status=CASE WHEN result_status='reconciled' THEN 'reconciled' ELSE status END,updated_at=now() WHERE id=h.id;
 INSERT INTO public.hsd_handoff_events(tenant_id,handoff_id,event_type,actor_id,correlation_id,payload) VALUES(h.tenant_id,h.id,CASE WHEN crit>0 THEN 'homeservice.handoff.discrepancy_found' ELSE 'homeservice.handoff.reconciled' END,p_actor_id,p_correlation_id,result_summary);
 RETURN QUERY SELECT result_status,crit,warn,result_summary;
END $$;
REVOKE ALL ON FUNCTION public.hsd_reconcile_carelink_handoff(uuid,text,uuid) FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.hsd_reconcile_carelink_handoff(uuid,text,uuid) TO service_role;

