COMMENT ON FUNCTION public.hsd_commit_carelink_handoff_core(uuid,text,uuid) IS 'UMZ4 atomic core: creates CARELINK parent and all dated sub-missions plus immutable lineage or commits nothing.';
COMMENT ON FUNCTION public.hsd_reconcile_carelink_handoff(uuid,text,uuid) IS 'UMZ4 deterministic reconciliation of snapshot mission count/dates/times/programme projection.';
COMMIT;
